<script setup lang="ts">
import { reactive } from 'vue'; import { useAssignReport, useReportTemplatesQuery, useTraineesQuery } from '@/api/queries/domainQueries'; import LcButton from '@/components/ui/LcButton.vue'; import LcCard from '@/components/ui/LcCard.vue'; import LcInput from '@/components/ui/LcInput.vue'; import LcSelect from '@/components/ui/LcSelect.vue'
const form = reactive({ traineeId: '', templateId: '', dueAt: '', note: '' }); const trainees = useTraineesQuery(); const templates = useReportTemplatesQuery(); const assign = useAssignReport(); const submit = () => assign.mutate({ traineeId: form.traineeId, templateId: form.templateId, dueAt: form.dueAt || undefined, note: form.note || undefined })
</script>
<template><section class="grid gap-6"><h1 class="font-display text-3xl font-bold">Report assignments</h1><LcCard><form class="grid gap-4" @submit.prevent="submit"><LcSelect v-model="form.traineeId" label="Trainee" :options="(trainees.data.value ?? []).map((t) => ({ label: t.name, value: t.id }))"/><LcSelect v-model="form.templateId" label="Template" :options="(templates.data.value ?? []).map((t) => ({ label: t.name, value: t.id }))"/><LcInput v-model="form.dueAt" label="Due date" type="datetime-local"/><LcInput v-model="form.note" label="Note"/><LcButton type="submit" :loading="assign.isPending.value">Assign frozen version</LcButton></form></LcCard></section></template>
